#[derive(Debug, PartialEq, Eq)]
pub(super) struct IncrementalGuideRecipe {
    pub recipe: String,
    pub modifier: String,
    pub inputs: Vec<String>,
    pub tools: Vec<String>,
    pub needed: i32,
    pub maximum: i32,
    pub upgrade_cost: i32,
